# Conventions

- ES modules, Node 20 or newer, no dependencies.
- Money is always whole cents (integers). Format with `formatEuros`, parse with `parseEuros` (src/money.js).
- Dates are plain `YYYY-MM-DD` strings in UTC; all date maths goes through src/dates.js.
- One module per file in `src/`, named exports only, a JSDoc comment on every exported function.
- Tests live in `test/<module>.test.js` and use `node:test` with `node:assert/strict`.
- Run the whole suite with `npm test` (it runs `node --test`).
- Two-space indentation, single quotes, semicolons.
import { addMonths } from './dates.js';

/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

/**
 * What a plan costs per month, in whole cents (cut to the cent).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  return Math.floor(sub.price / MONTHS_PER_CHARGE[sub.cycle]);
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}
// All dates are 'YYYY-MM-DD' strings and all maths is done in UTC, so the local time zone never matters.

const DAY_MS = 24 * 60 * 60 * 1000;
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function toUtc(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return Date.UTC(y, m - 1, d);
}

function fromUtc(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

/**
 * Check a date typed by a person. Returns the same 'YYYY-MM-DD' string, or null if it is not a real date.
 * @param {string} text
 * @returns {string | null}
 */
export function parseDate(text) {
  const s = String(text).trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  return fromUtc(toUtc(s)) === s ? s : null;
}

/**
 * Today's date in UTC.
 * @returns {string}
 */
export function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

/**
 * Add whole days: addDays('2026-12-30', 3) -> '2027-01-02'.
 * @param {string} iso
 * @param {number} days
 * @returns {string}
 */
export function addDays(iso, days) {
  return fromUtc(toUtc(iso) + days * DAY_MS);
}

/**
 * Add whole months, keeping the day of the month or using the last day of a shorter month:
 * addMonths('2026-01-31', 1) -> '2026-02-28'.
 * @param {string} iso
 * @param {number} months
 * @returns {string}
 */
export function addMonths(iso, months) {
  const [y, m, d] = iso.split('-').map(Number);
  const first = new Date(Date.UTC(y, m - 1 + months, 1));
  const lastDay = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0)).getUTCDate();
  return fromUtc(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), Math.min(d, lastDay)));
}

/**
 * Whole days from one date to another (negative if `to` is earlier).
 * @param {string} from
 * @param {string} to
 * @returns {number}
 */
export function daysBetween(from, to) {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/**
 * Short label for people: '2026-11-02' -> '2 Nov'.
 * @param {string} iso
 * @returns {string}
 */
export function shortLabel(iso) {
  const [, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTH_NAMES[m - 1]}`;
}
/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,299.00") into whole cents.
 * Returns null when the text is not an amount.
 * @param {string} text
 * @returns {number | null}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return null;
  return Number(m[1].replace(/,/g, '')) * 100 + Number((m[2] ?? '').padEnd(2, '0'));
}

/**
 * Format whole cents as euros: 123456 -> "€1,234.56".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Format whole cents as a plain decimal for files: 123456 -> "1234.56".
 * @param {number} cents
 * @returns {string}
 */
export function plainEuros(cents) {
  return (cents / 100).toFixed(2);
}
import { nextCharge } from './cycles.js';
import { daysBetween, shortLabel } from './dates.js';

/**
 * Charges coming up in the next `within` days (a charge today counts), soonest first.
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 * @param {string} today 'YYYY-MM-DD'
 * @param {number} [within=30]
 * @returns {Array<{ name: string, date: string, when: string, inDays: number, price: number, cycle: string }>}
 */
export function upcoming(subs, today, within = 30) {
  const rows = [];
  for (const sub of subs) {
    const date = nextCharge(sub, today);
    const inDays = daysBetween(today, date);
    if (inDays <= within) {
      rows.push({ name: sub.name, date, when: shortLabel(date), inDays, price: sub.price, cycle: sub.cycle });
    }
  }
  return rows.sort((a, b) => a.when.localeCompare(b.when) || a.name.localeCompare(b.name));
}
import { nextCharge } from './cycles.js';
import { plainEuros } from './money.js';

const HEADER = ['name', 'price', 'cycle', 'monthly_cost', 'next_charge'];

// how many months one charge pays for
const MONTHS = { monthly: 1, yearly: 12 };

function cell(value) {
  const s = String(value);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

/**
 * Subscriptions as CSV for a spreadsheet, one row per plan, with its monthly cost and next charge.
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 * @param {string} today 'YYYY-MM-DD'
 * @returns {string}
 */
export function toCsv(subs, today) {
  const lines = [HEADER.join(',')];
  for (const sub of subs) {
    const monthly = Math.floor(sub.price / MONTHS[sub.cycle]);
    lines.push([sub.name, plainEuros(sub.price), sub.cycle, plainEuros(monthly), nextCharge(sub, today)].map(cell).join(','));
  }
  return lines.join('\n') + '\n';
}
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { CYCLE, CYCLES } from './cycles.js';
import { parseDate } from './dates.js';

/**
 * Where the subscriptions are kept: `--file`, else $SUBTRACK_FILE, else ./subscriptions.json.
 * @param {string | undefined} file
 * @param {Record<string, string | undefined>} [env=process.env]
 * @returns {string}
 */
export function storePath(file, env = process.env) {
  return file || env.SUBTRACK_FILE || 'subscriptions.json';
}

/**
 * Why a subscription is not valid, or null if it is.
 * @param {{ name: string, price: number, cycle: string, since: string }} sub
 * @returns {string | null}
 */
export function validate(sub) {
  if (!sub || typeof sub.name !== 'string' || !sub.name.trim()) return 'a subscription needs a name';
  if (!Number.isInteger(sub.price) || sub.price < 0) return `${sub.name}: price must be whole cents, zero or more`;
  if (!CYCLES.includes(sub.cycle)) return `${sub.name}: unknown billing cycle "${sub.cycle}"`;
  if (parseDate(sub.since) === null) return `${sub.name}: "since" must be a date (YYYY-MM-DD)`;
  return null;
}

// Files written by subtrack 0.1 stored "month" and "year"; read them with today's cycle names.
const V1_NAMES = { month: CYCLE.MONTH, year: CYCLE.YEAR };

function upgrade(sub) {
  return { ...sub, cycle: V1_NAMES[sub.cycle] ?? sub.cycle };
}

/**
 * Read every subscription from the file (none if it does not exist yet). Throws on an invalid entry.
 * @param {string} path
 * @returns {Array<{ name: string, price: number, cycle: string, since: string }>}
 */
export function load(path) {
  if (!existsSync(path)) return [];
  const subs = (JSON.parse(readFileSync(path, 'utf8')).subscriptions ?? []).map(upgrade);
  for (const sub of subs) {
    const problem = validate(sub);
    if (problem) throw new Error(`${path}: ${problem}`);
  }
  return subs;
}

/**
 * Write every subscription to the file.
 * @param {string} path
 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
 */
export function save(path, subs) {
  writeFileSync(path, JSON.stringify({ subscriptions: subs }, null, 2) + '\n');
}
#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { CYCLE, monthlyCents } from '../src/cycles.js';
import { parseDate, todayIso } from '../src/dates.js';
import { toCsv } from '../src/export.js';
import { formatEuros, parseEuros } from '../src/money.js';
import { upcoming } from '../src/renewals.js';
import { load, save, storePath, validate } from '../src/store.js';

const USAGE = `usage: subtrack <command> [options]

  add <name> <price> [--every month|year] [--since YYYY-MM-DD]
  list
  total
  renewals [--within <days>]
  export
  remove <name>

options for every command: --file <path>, --today YYYY-MM-DD`;

// how much of one charge falls in a month
const SHARE_PER_MONTH = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 1 / 12 };

function die(message, code = 1) {
  process.stderr.write(`subtrack: ${message}\n`);
  process.exit(code);
}

// --every month|year (monthly/yearly work too)
const EVERY = { month: CYCLE.MONTH, monthly: CYCLE.MONTH, year: CYCLE.YEAR, yearly: CYCLE.YEAR };

function cycleFlag(value = 'month') {
  const cycle = EVERY[value.toLowerCase()];
  if (!cycle) die(`--every must be month or year, got "${value}"`, 2);
  return cycle;
}

let parsed;
try {
  parsed = parseArgs({
    args: process.argv.slice(2),
    allowPositionals: true,
    options: {
      every: { type: 'string' },
      since: { type: 'string' },
      within: { type: 'string' },
      today: { type: 'string' },
      file: { type: 'string' },
      help: { type: 'boolean', short: 'h' },
    },
  });
} catch (err) {
  die(`${err.message}\n\n${USAGE}`, 2);
}
const { values: opts, positionals } = parsed;
const [command, ...args] = positionals;
if (opts.help || !command) {
  console.log(USAGE);
  process.exit(command || opts.help ? 0 : 2);
}

const file = storePath(opts.file);
const today = opts.today === undefined ? todayIso() : parseDate(opts.today);
if (today === null) die(`--today must be a date (YYYY-MM-DD), got "${opts.today}"`, 2);

let subs;
try {
  subs = load(file);
} catch (err) {
  die(err.message);
}

switch (command) {
  case 'add': {
    const [name, priceText] = args;
    if (!name || priceText === undefined) die(`add needs a name and a price\n\n${USAGE}`, 2);
    const price = parseEuros(priceText);
    if (price === null) die(`"${priceText}" is not a price (try 12.99)`, 2);
    const since = opts.since === undefined ? today : parseDate(opts.since);
    if (since === null) die(`--since must be a date (YYYY-MM-DD), got "${opts.since}"`, 2);
    if (subs.some((s) => s.name.toLowerCase() === name.toLowerCase())) die(`${name} is already on the list`);
    const sub = { name, price, cycle: cycleFlag(opts.every), since };
    const problem = validate(sub);
    if (problem) die(problem, 2);
    subs.push(sub);
    save(file, subs);
    console.log(`Added ${name}: ${formatEuros(price)} ${sub.cycle}, ${formatEuros(monthlyCents(sub))} a month.`);
    break;
  }
  case 'list': {
    if (!subs.length) {
      console.log('No subscriptions yet. Add one with: subtrack add <name> <price>');
      break;
    }
    const width = Math.max(...subs.map((s) => s.name.length));
    for (const s of subs) {
      console.log(`${s.name.padEnd(width)}  ${formatEuros(s.price).padStart(10)} ${s.cycle.padEnd(8)} ${formatEuros(monthlyCents(s)).padStart(10)} a month`);
    }
    break;
  }
  case 'total': {
    // add up the exact amounts and cut to the cent once, so cut-off cents don't pile up across plans
    const total = Math.floor(subs.reduce((sum, s) => sum + s.price * (SHARE_PER_MONTH[s.cycle] ?? 0), 0) + 1e-9);
    console.log(`Monthly total: ${formatEuros(total)} (${subs.length} ${subs.length === 1 ? 'plan' : 'plans'})`);
    break;
  }
  case 'renewals': {
    const within = opts.within === undefined ? 30 : Number(opts.within);
    if (!Number.isInteger(within) || within < 0) die(`--within must be a whole number of days, got "${opts.within}"`, 2);
    const rows = upcoming(subs, today, within);
    if (!rows.length) {
      console.log(`Nothing renews in the next ${within} days.`);
      break;
    }
    const width = Math.max(...rows.map((r) => r.name.length));
    for (const r of rows) {
      console.log(`${r.when.padEnd(6)}  ${r.name.padEnd(width)}  ${formatEuros(r.price)}`);
    }
    break;
  }
  case 'export':
    process.stdout.write(toCsv(subs, today));
    break;
  case 'remove': {
    const [name] = args;
    const left = subs.filter((s) => s.name.toLowerCase() !== String(name).toLowerCase());
    if (left.length === subs.length) die(`${name} is not on the list`);
    save(file, left);
    console.log(`Removed ${name}.`);
    break;
  }
  default:
    die(`unknown command "${command}"\n\n${USAGE}`, 2);
}
