import { addDays, addMonths } from './dates.js';

/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ WEEK: 'weekly', MONTH: 'monthly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };
const DAYS_PER_CHARGE = { [CYCLE.WEEK]: 7 };

// a charge's monthly cost is price * NUMERATOR / 12 (a week is 52/12 of a month's share)
const TWELFTHS_PER_MONTH = { [CYCLE.WEEK]: 52, [CYCLE.MONTH]: 12, [CYCLE.YEAR]: 1 };

/**
 * A plan's monthly cost in twelfths of a cent, exact (for adding up plans before rounding once).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyTwelfths(sub) {
  return sub.price * (TWELFTHS_PER_MONTH[sub.cycle] ?? 0);
}

/**
 * Round an amount in twelfths of a cent to the nearest whole cent (halves go up).
 * @param {number} twelfths
 * @returns {number}
 */
export function roundTwelfths(twelfths) {
  return Math.floor((twelfths + 6) / 12);
}

/**
 * What a plan costs per month, in whole cents (rounded to the nearest cent).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  return roundTwelfths(monthlyTwelfths(sub));
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Monthly and yearly charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
 * Weekly charges fall every 7 days from `since`.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  const days = DAYS_PER_CHARGE[sub.cycle];
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = days ? addDays(sub.since, n * days) : addMonths(sub.since, n * step);
  }
  return date;
}
EOF
